import {plan,csv} from './core.js';import {catalogs} from './locales.js';
const lang=document.documentElement.lang,c=catalogs[lang]||catalogs.ko,$=id=>document.getElementById(id),num=new Intl.NumberFormat(lang,{maximumFractionDigits:2});let result=null;
document.title=c.title;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=c[el.dataset.i18n]);document.querySelector('.languages').setAttribute('aria-label',c.language);document.querySelector(`[data-lang="${lang}"]`).setAttribute('aria-current','page');
function status(s,error=false){$('status').textContent=s;$('status').classList.toggle('error',error);}
function stale(){result=null;document.querySelectorAll('[data-export]').forEach(b=>b.disabled=true);['required','available','shortfall','bufferTotal'].forEach(id=>$(id).textContent='—');$('days').replaceChildren();$('taskResults').replaceChildren();status(c.stale);}
function addTask(t={name:c.newTask,hours:'1',priority:3}){if($('tasks').children.length>=30){status(c.errors.tasks,true);return;}const tr=document.createElement('tr');for(const [key,label,type] of [['name',c.name,'text'],['hours',c.estimate,'number'],['priority',c.priority,'select']]){const td=document.createElement('td');td.dataset.label=label;let input;if(type==='select'){input=document.createElement('select');for(let i=1;i<=5;i++){const o=document.createElement('option');o.value=i;o.textContent=i;input.append(o);}}else{input=document.createElement('input');input.type=type;if(type==='number'){input.min='0.01';input.max='1000';input.step='0.01';}else input.maxLength=120;}input.dataset.key=key;input.value=t[key];input.setAttribute('aria-label',label);input.oninput=stale;input.onchange=stale;td.append(input);tr.append(td);}const td=document.createElement('td'),b=document.createElement('button');b.textContent=c.remove;b.className='delete';b.onclick=()=>{tr.remove();stale();};td.append(b);tr.append(td);$('tasks').append(tr);stale();}
function readTasks(){return [...$('tasks').children].map(tr=>Object.fromEntries([...tr.querySelectorAll('input,select')].map(i=>[i.dataset.key,i.value])));}
function mins(m){return `${num.format(m/60)} ${c.hours} · ${m} ${c.minutes}`;}
function appendRow(body,values){const tr=document.createElement('tr');for(const value of values){const td=document.createElement('td');td.textContent=String(value);tr.append(td);}$(body).append(tr);}
function run(){stale();try{result=plan({start:$('start').value,deadline:$('deadline').value,buffer:$('buffer').value,tasks:readTasks(),capacity:$('capacity').value});$('required').textContent=mins(result.required);$('available').textContent=mins(result.totalCapacity);$('shortfall').textContent=mins(result.missing);$('bufferTotal').textContent=mins(result.bufferMinutes);for(const d of result.days){if(!d.items.length)appendRow('days',[d.date,c.idle,'0',d.left]);for(const i of d.items)appendRow('days',[d.date,`${i.task} [${i.priority}]`,i.minutes,d.left]);}for(const t of result.tasks)appendRow('taskResults',[t.name,t.need,t.allocated,t.missing]);document.querySelectorAll('[data-export]').forEach(b=>b.disabled=false);status(result.feasible?c.feasible:c.impossible.replace('{n}',result.missing),!result.feasible);}catch(e){status((c.errors[e.code]||c.errors.unknown)+(e.detail||''),true);}}
function example(){$('start').value='2026-10-26';$('deadline').value='2026-11-01';$('buffer').value='20';$('capacity').value='2026-10-26,1\n2026-10-27,2\n2026-10-28,1.5\n2026-10-29,2\n2026-10-30,1\n2026-10-31,3\n2026-11-01,2';$('tasks').replaceChildren();c.sampleNames.forEach((name,i)=>addTask({name,hours:['2','4','1'][i],priority:i+1}));run();}
function exportText(){return csv(result,{header:[c.day,c.name,c.priority,c.allocated,c.available,c.remaining,c.status],idle:c.idle,scheduled:c.scheduled,missing:c.missing});}
$('add').onclick=()=>addTask();$('example').onclick=example;$('calculate').onclick=run;['start','deadline','buffer','capacity'].forEach(id=>$(id).addEventListener('input',stale));
$('download').onclick=()=>{if(!result)return;const url=URL.createObjectURL(new Blob([exportText()],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='deadline-plan.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status(c.saved);};
$('copy').onclick=async()=>{if(!result)return;try{await navigator.clipboard.writeText(exportText().replace(/^\uFEFF/,''));status(c.copied);}catch{status(c.copyError,true);}};example();
